import { test, expect } from '@playwright/test';

/** A role credential from the environment; fails clearly when it is not set. */
function credential(name: string, value: string | undefined): string {
  if (!value) throw new Error(`Environment variable ${name} is not set`);
  return value;
}

test('SCN-0002: Prevent login when the username is empty', async ({ page }) => {
  // Expected (REQ-001): Empty username: login is prevented and the message Epic sadface: Username is required is shown.
  await page.goto('/');
  await page.getByRole('textbox', { name: 'Password', exact: true }).fill(credential('SAUCEDEMO_STANDARD_USER_PASSWORD', process.env.SAUCEDEMO_STANDARD_USER_PASSWORD));
  await page.getByRole('button', { name: 'Login', exact: true }).click();
  await expect(page.getByText('Epic sadface: Username is required', { exact: true })).toBeVisible();
});
